// Export a local example travel to demo/fixtures.json + demo/assets for cmd/seed-demo (LOCAL DEV ONLY).
// Usage: node scripts/export-demo-fixtures.mjs <tenant_id>   (MYSQL_BIN overrides the mysql client path;
// connects as root without password, the Laragon default). Run from the repo root.
// Content only (profile, packages, banners, testimonials, FAQ, images). People, prospects and activity are
// generated by the seeder. Departure dates become offsets in days from the export date.
import { execFileSync } from 'child_process';
import fs from 'fs';
import path from 'path';

const MYSQL = process.env.MYSQL_BIN || 'C:/laragon/bin/mysql/mysql-8.4.3-winx64/bin/mysql.exe';
const ROOT = process.cwd();
const T = Number(process.argv[2]);
if (!Number.isInteger(T) || T <= 0) {
  console.error('usage: node scripts/export-demo-fixtures.mjs <tenant_id>');
  process.exit(1);
}
const q = (sql) =>
  JSON.parse(
    execFileSync(MYSQL, ['-uroot', '--default-character-set=utf8mb4', '-N', '-B', '--raw', 'klikumroh', '-e', sql], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 }).trim() || 'null',
  );
const rows = (table, cols, where) =>
  q(`SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT(${cols.map((c) => `'${c}', ${c}`).join(', ')})), JSON_ARRAY()) FROM (SELECT * FROM ${table} WHERE ${where}) x`);

const assets = path.join(ROOT, 'demo', 'assets');
fs.rmSync(assets, { recursive: true, force: true });
const copy = (url) => {
  if (!url) return null;
  const rel = url.replace(/^\/uploads\/\d+\//, '');
  const src = path.join(ROOT, 'uploads', String(T), rel);
  if (!fs.existsSync(src)) return null;
  const dst = path.join(assets, rel);
  fs.mkdirSync(path.dirname(dst), { recursive: true });
  fs.copyFileSync(src, dst);
  return rel.replace(/\\/g, '/');
};

const tenantCols = [
  'name', 'brand_primary_color', 'brand_logo_url', 'brand_icon_url', 'tagline', 'about_summary', 'ppiu_number', 'address', 'city', 'province', 'phone', 'email',
  'trust_rating', 'trust_alumni_count', 'trust_guarantee', 'social_instagram', 'social_facebook', 'social_youtube', 'meta_title', 'meta_description', 'meta_keywords',
  'commission_override_enabled', 'commission_override_percentage', 'agent_registration_fee', 'agent_registration_benefits', 'agent_terms_conditions',
  'minimum_payout_amount', 'commission_release_on',
];
const tenant = rows('tenants', tenantCols, `id = ${T}`)[0];
tenant.brand_logo = copy(tenant.brand_logo_url);
tenant.brand_icon = copy(tenant.brand_icon_url);
delete tenant.brand_logo_url;
delete tenant.brand_icon_url;

const today = new Date(new Date().toISOString().slice(0, 10) + 'T00:00:00Z');
const pkgCols = ['id', 'name', 'description', 'price', 'departure_date', 'quota', 'status', 'itinerary', 'facilities_included', 'facilities_excluded', 'hotel_info', 'flight_info', 'terms_conditions', 'commission_amount'];
const pkgs = rows('packages', pkgCols, `tenant_id = ${T} AND status = 'published' ORDER BY departure_date`);
const photos = rows('package_photos', ['package_id', 'file_path', 'sort_order'], `tenant_id = ${T} ORDER BY package_id, sort_order`);
const pkgIndex = new Map();
const packages = pkgs.map((p, i) => {
  pkgIndex.set(p.id, i);
  const days = p.departure_date ? Math.round((new Date(p.departure_date + 'T00:00:00Z') - today) / 86400000) : null;
  const out = { ...p, departure_offset_days: days, photos: photos.filter((ph) => ph.package_id === p.id).map((ph) => copy(ph.file_path)).filter(Boolean) };
  delete out.id;
  delete out.departure_date;
  return out;
});

const banners = rows('tenant_banners', ['title', 'subtitle', 'image_url', 'cta_url', 'display_order', 'is_active'], `tenant_id = ${T} ORDER BY display_order`).map((b) => {
  const m = /^\/paket\/(\d+)$/.exec(b.cta_url || '');
  return { title: b.title, subtitle: b.subtitle, image: copy(b.image_url), cta_package: m ? pkgIndex.get(Number(m[1])) ?? null : null, cta_url: m ? null : b.cta_url, display_order: b.display_order, is_active: b.is_active };
});
const testimonials = rows('tenant_testimonials', ['name', 'package_name', 'rating', 'quote', 'avatar_url', 'display_order', 'is_active'], `tenant_id = ${T} ORDER BY display_order`).map((t) => ({ ...t, avatar: copy(t.avatar_url), avatar_url: undefined }));
const faqs = rows('tenant_faqs', ['question', 'answer', 'display_order', 'is_active'], `tenant_id = ${T} ORDER BY display_order`);
// Photo for the demo agent account (the portal's ID card and leaderboard).
// The first agent photo found becomes the photo of the demo agent login.
const firstPhoto = q(`SELECT JSON_ARRAY(photo_url) FROM agents WHERE tenant_id = ${T} AND photo_url IS NOT NULL ORDER BY id LIMIT 1`);
const agentPhoto = firstPhoto ? copy(firstPhoto[0]) : null;

const fixtures = { exported_at: today.toISOString().slice(0, 10), tenant, packages, banners, testimonials, faqs, agent_photo: agentPhoto };
fs.writeFileSync(path.join(ROOT, 'demo', 'fixtures.json'), JSON.stringify(fixtures, null, 2) + '\n');
const count = (dir) => fs.readdirSync(dir, { withFileTypes: true }).reduce((n, e) => n + (e.isDirectory() ? count(path.join(dir, e.name)) : 1), 0);
console.log({ packages: packages.length, banners: banners.length, testimonials: testimonials.length, faqs: faqs.length, assets: count(assets), offsets: packages.map((p) => p.departure_offset_days) });
